#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minPairSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int maxPairSum = 0;
        int left = 0;
        int right = static_cast<int>(nums.size()) - 1;

        while (left < right) {
            int currentSum = nums[left] + nums[right];
            maxPairSum = max(maxPairSum, currentSum);
            left++;
            right--;
        }

        return maxPairSum;
    }
};

