/**
 * @param {number[]} nums
 * @return {number}
 */
var minPairSum = function(nums) {
    nums.sort((a, b) => a - b);
    let maxPairSum = 0;
    let left = 0;
    let right = nums.length - 1;

    while (left < right) {
        const currentSum = nums[left] + nums[right];
        if (currentSum > maxPairSum) {
            maxPairSum = currentSum;
        }
        left++;
        right--;
    }

    return maxPairSum;
};
